const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,PARENT=process.env.PARENT_SHA,PARENT_BLOB=process.env.PARENT_BLOB,TARGET_BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES);const assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important,winnerSelector:l.selector,winnerContext:l.context});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
assert(sh(`git rev-parse ${PARENT}:${TARGET}`)===PARENT_BLOB,'parent blob drift');const parent=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`],{encoding:'utf8'}),p=parse(parent);assert(p.declarations.length===50&&p.dead.length===1,`parent parse drift ${p.declarations.length}/${p.dead.length}`);const d=p.dead[0];assert(d.line===23&&d.winnerLine===205,'cascade line drift');assert(d.property==='box-shadow'&&d.value==='var(--profile-surface-shadow)'&&d.winnerValue==='var(--doke-shadow-nested-soft)','cascade value drift');assert(d.selector===d.winnerSelector&&d.context===d.winnerContext&&d.important===d.winnerImportant,'unconditional dominance drift');const nl=/\r?\n$/.test(parent),lines=parent.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();assert(lines[22]?.trim()==='box-shadow: var(--profile-surface-shadow);','source line mismatch');lines.splice(22,1);const rebuilt=Buffer.from(lines.join('\n')+(nl?'\n':''));const current=fs.readFileSync(TARGET);assert(crypto.createHash('sha1').update(Buffer.concat([Buffer.from(`blob ${current.length}\0`),current])).digest('hex')===TARGET_BLOB,'target blob content drift');assert(rebuilt.equals(current),'independent reconstruction differs from permanent');const after=parse(current.toString('utf8'));assert(after.declarations.length===49&&after.dead.length===0,`permanent parse drift ${after.declarations.length}/${after.dead.length}`);const hash=crypto.createHash('sha256').update(current).digest('hex');assert(hash===HASH,`hash drift ${hash}`);assert(current.length===BYTES,`bytes drift ${current.length}`);console.log(`EXACT BYTE IDENTITY PASS|parent=${PARENT}|parentBlob=${PARENT_BLOB}|targetBlob=${TARGET_BLOB}|hash=${hash}|bytes=${current.length}|decl=50->49|dead=1->0|families=1|staticCascadeRows=1|unconditionalDominance=1`);
